/// Control name ("mode_chill", "color_red", "fx1") to trigger name ("mode.chill", "color.red",
/// "fx.1") from Annex B.3 of the specification.
QString triggerName(const QString& control) {
    if (control.startsWith(QLatin1String("mode_")) || control.startsWith(QLatin1String("color_"))) {
        QString name = control;
        name.replace(name.indexOf(QLatin1Char('_')), 1, QLatin1Char('.'));
        return name;
    }
    if (control.startsWith(QLatin1String("fx"))) {
        return QStringLiteral("fx.") + control.mid(2);
    }
    return control;
}

/// Makes VisualPlayPosition return the position of the sample at the DAC right now.
class NowTimeProvider : public VSyncTimeProvider {
  public:
    std::chrono::microseconds fromTimerToNextSync(const PerformanceTimer& timer) override {
        return std::chrono::microseconds(timer.elapsed().toIntegerMicros());
    }
    std::chrono::microseconds getSyncInterval() const override {
        return std::chrono::microseconds(16667);
    }
};

/// Mixxx EQ gain (0..4, 1 = neutral) to the 0..1 range of the spec (0.5 = neutral).
double eqNormalized(double gain) {
    if (gain <= 1.0) {
        return 0.5 * std::max(0.0, gain);
    }
    return 0.5 + 0.5 * std::min(1.0, (gain - 1.0) / 3.0);
}

double round3(double v) {
    return std::round(v * 1000.0) / 1000.0;
}

QString intensityFor(double energy) {
    if (energy < 0.4) {
        return QStringLiteral("low");
    }
    if (energy < 0.65) {
        return QStringLiteral("medium");
    }
    if (energy < 0.9) {
        return QStringLiteral("high");
    }
    return QStringLiteral("peak");
}

