/// A control that may be created after us (EQ and quick effect racks): retried every 2 s.
class VertexAVManager::LazyControl {
  public:
    explicit LazyControl(ConfigKey key)
            : m_key(std::move(key)) {
    }
    double get(double defaultValue) {
        if (!m_pProxy || !m_pProxy->valid()) {
            if (m_retry.isValid() && m_retry.elapsed() < 2000) {
                return defaultValue;
            }
            m_retry.start();
            m_pProxy = std::make_unique<PollingControlProxy>(m_key, ControlFlag::NoWarnIfMissing);
            if (!m_pProxy->valid()) {
                return defaultValue;
            }
        }
        return m_pProxy->get();
    }

  private:
    ConfigKey m_key;
    std::unique_ptr<PollingControlProxy> m_pProxy;
    QElapsedTimer m_retry;
};

