void VertexAVManager::createTriggerControls() {
    for (const QString& control : kTriggerControls) {
        auto pButton = std::make_unique<ControlPushButton>(
                ConfigKey(kConfigGroup, QStringLiteral("trigger_") + control));
        const QString name = triggerName(control);
        connect(pButton.get(), &ControlObject::valueChanged, this, [this, name](double value) {
            if (m_pEmitter) {
                m_pEmitter->trigger(name, value > 0 ? QStringLiteral("on") : QStringLiteral("off"));
            }
        });
        m_triggers.push_back(std::move(pButton));
    }
}

void VertexAVManager::slotEnabledChanged(double value) {
    if (value > 0) {
        start();
    } else {
        stop();
    }
}

void VertexAVManager::slotSettingsChanged(double value) {
    if (value <= 0) {
        return;
    }
    if (isRunning()) {
        stop();
        start();
    }
}

void VertexAVManager::slotNumberOfDecksChanged(int decks) {
    Q_UNUSED(decks);
    setupDecks();
}

void VertexAVManager::setupDecks() {
    const int count = m_pPlayerManager->numberOfDecks();
    for (int i = static_cast<int>(m_decks.size()); i < count; ++i) {
        m_decks.push_back(std::make_unique<DeckState>(i + 1, PlayerManager::groupForDeck(i)));
        Deck* pDeck = m_pPlayerManager->getDeck(i);
        if (!pDeck) {
            continue;
        }
        connect(pDeck, &BaseTrackPlayer::newTrackLoaded, this, [this, i](TrackPointer pTrack) {
            onTrackLoaded(i, pTrack);
        });
        connect(pDeck, &BaseTrackPlayer::playerEmpty, this, [this, i] {
            onTrackUnloaded(i);
        });
        if (TrackPointer pTrack = pDeck->getLoadedTrack()) {
            onTrackLoaded(i, pTrack);
        }
    }
}

void VertexAVManager::start() {
    if (m_pEmitter) {
        return;
    }
    const QString group = kConfigGroup;
    QString id = m_pConfig->getValueString(ConfigKey(group, QStringLiteral("id")));
    if (id.isEmpty()) {
        id = QStringLiteral("vx-") +
                QString::fromLatin1(vertexav::security::randomBytes(4).toHex());
        m_pConfig->setValue(ConfigKey(group, QStringLiteral("id")), id);
    }
    vertexav::EmitterConfig cfg;
    cfg.id = id;
    cfg.name = m_pConfig->getValue(ConfigKey(group, QStringLiteral("name")), QStringLiteral("Mixxx"));
    cfg.port = static_cast<quint16>(m_pConfig->getValue(ConfigKey(group, QStringLiteral("port")), 9470));
    cfg.udpPort = static_cast<quint16>(
            m_pConfig->getValue(ConfigKey(group, QStringLiteral("udp_port")), 9471));
    cfg.lookaheadUs = 1000LL *
            m_pConfig->getValue(ConfigKey(group, QStringLiteral("lookahead_ms")), 150);
    cfg.announce = m_pConfig->getValue(ConfigKey(group, QStringLiteral("announce")), true);
    cfg.decks = static_cast<int>(m_decks.size());
    cfg.profiles = {0, 1, 2};
    const bool localOnly = m_pConfig->getValue(ConfigKey(group, QStringLiteral("local_only")), false);
    cfg.host = localOnly ? QHostAddress(QHostAddress::LocalHost) : QHostAddress(QHostAddress::AnyIPv4);
    cfg.security = m_pConfig->getValue(ConfigKey(group, QStringLiteral("security")), QStringLiteral("open"));
    if (cfg.security == QLatin1String("auth")) {
        bool ok = false;
        cfg.psk = vertexav::security::codeToPsk(
                m_pConfig->getValueString(ConfigKey(group, QStringLiteral("pairing_code"))), &ok);
        if (!ok) {
            qWarning() << "VertexAV: security is 'auth' but the pairing code is invalid; not starting";
            return;
        }
    } else if (!localOnly) {
        qWarning() << "VertexAV: running in 'open' mode on the network: anyone on the network "
                      "can connect (see the security section of the specification)";
    }
    m_extraLatencyUs = 1000LL * m_pConfig->getValue(ConfigKey(group, QStringLiteral("output_offset_ms")), 0);

    m_pThread = new QThread();
    m_pThread->setObjectName(QStringLiteral("VertexAV"));
    m_pEmitter = new vertexav::Emitter(cfg);
    m_pEmitter->moveToThread(m_pThread);
    connect(m_pThread, &QThread::finished, m_pEmitter, &QObject::deleteLater);
    m_pThread->start();
    bool started = false;
    QString error;
    vertexav::Emitter* pEmitter = m_pEmitter;
    QMetaObject::invokeMethod(
            pEmitter, [pEmitter, &started, &error] { started = pEmitter->start(&error); }, Qt::BlockingQueuedConnection);
    if (!started) {
        qWarning() << "VertexAV: could not start the emitter:" << error;
        m_pThread->quit();
        m_pThread->wait();
        delete m_pThread;
        m_pThread = nullptr;
        m_pEmitter = nullptr;
        return;
    }
    qInfo() << "VertexAV: emitter" << m_pEmitter->id() << "listening on port" << m_pEmitter->port()
            << "/ UDP" << m_pEmitter->udpPort() << "security" << cfg.security;

    m_pMix = std::make_unique<vertexav::MixAnalyzer>();
    m_pTempo = std::make_unique<vertexav::Tempo>();
    m_pTempo->playing = false;
    m_needsReanchor = true;
    m_sourceDeck = 0;
    m_announced.clear();
    m_doneEvents.clear();
    m_currentSection = -1;
    m_currentSectionDeck = 0;
    m_sentCrossfader = -2;
    for (auto& pDeck : m_decks) {
        pDeck->sentContinuous = QJsonObject();
        pDeck->sentRate = pDeck->sentBpm = -1;
        pDeck->lastT = -1;
        if (pDeck->track) {
            publishTrack(*pDeck);
        }
    }
    m_pollTimer.start();
}

void VertexAVManager::stop() {
    m_pollTimer.stop();
    if (!m_pEmitter) {
        return;
    }
    vertexav::Emitter* pEmitter = m_pEmitter;
    QMetaObject::invokeMethod(
            pEmitter, [pEmitter] { pEmitter->stop(); }, Qt::BlockingQueuedConnection);
    m_pThread->quit(); // the emitter is deleted when the thread finishes
    m_pThread->wait();
    delete m_pThread;
    m_pThread = nullptr;
    m_pEmitter = nullptr;
    m_pReceivers->forceSet(0);
}

// ------------------------------------------------------------------ tracks

void VertexAVManager::onTrackLoaded(int deckIndex, TrackPointer pTrack) {
    if (deckIndex < 0 || deckIndex >= static_cast<int>(m_decks.size())) {
        return;
    }
    DeckState& deck = *m_decks[deckIndex];
    for (const auto& c : std::as_const(deck.trackConnections)) {
        disconnect(c);
    }
    deck.trackConnections.clear();
    deck.track = pTrack;
    deck.cacheBeat = deck.cacheBeatSlip = mixxx::audio::FramePos();
    deck.lastT = -1;
    if (!pTrack) {
        onTrackUnloaded(deckIndex);
        return;
    }
    // The track may be changed from other threads (analysis): handle it in ours.
    auto markDirty = [this, deckIndex] {
        if (deckIndex < static_cast<int>(m_decks.size())) {
            m_decks[deckIndex]->dirty = true;
        }
    };
    deck.trackConnections.append(
            connect(pTrack.get(), &Track::beatsUpdated, this, markDirty, Qt::QueuedConnection));
    deck.trackConnections.append(
            connect(pTrack.get(), &Track::cuesUpdated, this, markDirty, Qt::QueuedConnection));
    if (m_pEmitter) {
        publishTrack(deck);
    } else {
        deck.beats = pTrack->getBeats();
    }
    if (deck.number == m_sourceDeck) {
        m_needsReanchor = true;
    }
}

void VertexAVManager::onTrackUnloaded(int deckIndex) {
    if (deckIndex < 0 || deckIndex >= static_cast<int>(m_decks.size())) {
        return;
    }
    DeckState& deck = *m_decks[deckIndex];
    if (deck.number == m_sourceDeck) {
        m_needsReanchor = true;
    }
    deck.track.reset();
    deck.beats.reset();
    deck.info = mixxx::vertexav::TrackInfo();
    deck.hasPosition = false;
    if (m_pEmitter) {
        m_pEmitter->trackUnloaded(deck.number);
    }
}

void VertexAVManager::publishTrack(DeckState& deck) {
    if (!deck.track || !m_pEmitter) {
        return;
    }
    deck.dirty = false;
    deck.beats = deck.track->getBeats();
    const auto rate = deck.track->getSampleRate();
    deck.sampleRate = rate.isValid() ? rate.toDouble() : 44100.0;
    deck.info = mixxx::vertexav::buildTrackInfo(deck.track);
    m_pEmitter->trackLoaded(deck.number,
            deck.info.trackId,
            deck.info.meta,
            deck.info.hasSections || deck.beats != nullptr);
    if (deck.beats) {
        m_pEmitter->trackStructure(deck.info.structure);
    }
}

QJsonObject VertexAVManager::positionFields(const DeckState& deck) const {
    QJsonObject o;
    o[QStringLiteral("position_s")] = round3(deck.positionS);
    o[QStringLiteral("position_beat")] = round3(deck.beat);
    o[QStringLiteral("rate")] = std::round(deck.rate * 100000.0) / 100000.0;
    o[QStringLiteral("bpm")] = deck.effectiveBpm > 0 ? QJsonValue(round3(deck.effectiveBpm)) : QJsonValue();
    return o;
}

// ------------------------------------------------------------------ polling

void VertexAVManager::slotPoll() {
    if (!m_pEmitter) {
        return;
    }
    const qint64 now = m_pEmitter->now();
    QMap<int, double> audible;
    for (auto& pDeck : m_decks) {
        if (pDeck->dirty) {
            publishTrack(*pDeck);
        }
        pollDeck(*pDeck, now);
        audible.insert(pDeck->number, pDeck->audible);
    }

    // Mix analysis (§10.2)
    const DeckState* pSource = m_sourceDeck > 0 && m_sourceDeck <= static_cast<int>(m_decks.size())
            ? m_decks[m_sourceDeck - 1].get()
            : nullptr;
    const double beatUs = pSource && pSource->effectiveBpm > 0 ? 60e6 / pSource->effectiveBpm : 500000.0;
    const vertexav::MixResult mix = m_pMix->update(audible, now, beatUs);
    if (!mix.mix.isEmpty()) {
        m_pEmitter->updateMix(mix.mix);
    }
    for (const vertexav::MixEvent& e : mix.events) {
        m_pEmitter->event(e.name, -1, e.deck, e.data);
    }
    const double crossfader = round3(m_pCrossfader->get());
    if (crossfader != m_sentCrossfader) {
        m_sentCrossfader = crossfader;
        m_pEmitter->updateMix(QJsonObject{{QStringLiteral("crossfader"), crossfader}});
    }
    if (mix.onAirChanged || (m_pMix->onAir() > 0 && m_pMix->onAir() != m_sourceDeck)) {
        if (m_sourceDeck > 0) {
            m_pEmitter->updateDeck(m_sourceDeck, QJsonObject{{QStringLiteral("on_air"), false}});
        }
        m_sourceDeck = m_pMix->onAir();
        m_pEmitter->updateDeck(m_sourceDeck, QJsonObject{{QStringLiteral("on_air"), true}});
        m_needsReanchor = true;
    }
    if (m_sourceDeck == 0) {
        for (auto& pDeck : m_decks) {
            if (pDeck->playing && pDeck->beats) {
                m_sourceDeck = pDeck->number;
                m_needsReanchor = true;
                break;
            }
        }
    }
    updateTempo(now);
    scheduleSectionEvents(now);
    trackSections(now);
    const int receivers = m_pEmitter->receiverCount();
    if (m_pReceivers->get() != receivers) {
        m_pReceivers->forceSet(receivers);
    }
}

void VertexAVManager::pollDeck(DeckState& deck, qint64 now) {
    const bool loaded = deck.track != nullptr;
    const bool playing = loaded && deck.play->get() > 0;
    const bool scratching = loaded && deck.scratch->get() > 0;
    const bool slip = loaded && deck.slip->get() > 0;
    const bool loopOn = loaded && deck.loopEnabled->get() > 0;
    const bool pflOn = deck.pfl->get() > 0;
    const double fader = std::clamp(deck.volume->get(), 0.0, 1.0);

    // Audible: channel fader x crossfader gain of the deck's side.
    CSAMPLE_GAIN left = 1.0f;
    CSAMPLE_GAIN right = 1.0f;
    EngineXfader::getXfadeGains(m_pCrossfader->get(),
            m_pXfaderCurve->get(),
            m_pXfaderCalibration->get(),
            m_pXfaderMode->get(),
            m_pXfaderReverse->get() > 0,
            &left,
            &right);
    const int orientation = static_cast<int>(deck.orientation->get());
    const double gain = orientation == 0 ? left : (orientation == 2 ? right : 1.0);
    deck.audible = playing ? round3(std::clamp(fader * gain, 0.0, 1.0)) : 0.0;

    // Position of the sample the audience hears now.
    deck.hasPosition = false;
    if (loaded && deck.beats) {
        double pos = 0;
        double slipPos = 0;
        NowTimeProvider nowProvider;
        if (deck.vpp && deck.vpp->getPlaySlipAtNextVSync(&nowProvider, &pos, &slipPos)) {
            const double trackFrames = deck.trackSamples->get() / mixxx::kEngineChannelOutputCount;
            const mixxx::audio::FramePos frame(pos * trackFrames);
            const mixxx::audio::FramePos slipFrame(slipPos * trackFrames);
            deck.beat = mixxx::vertexav::beatIndexAt(deck.beats, frame, &deck.cacheBeat, &deck.cacheIndex);
            deck.slipBeat = mixxx::vertexav::beatIndexAt(
                    deck.beats, slipFrame, &deck.cacheBeatSlip, &deck.cacheIndexSlip);
            deck.positionS = frame.value() / deck.sampleRate;
            deck.slipPositionS = slipFrame.value() / deck.sampleRate;
            deck.hasPosition = true;
            deck.goodBeat = deck.beat;
            deck.goodT = now;
        } else if (playing && deck.goodT >= 0 && now - deck.goodT < 1000000 && deck.effectiveBpm > 0) {
            // With a long audio output queue the buffer at the DAC may not be known yet:
            // keep the timeline going from the last good position instead of dropping it.
            deck.beat = deck.goodBeat + (now - deck.goodT) / 1e6 * deck.effectiveBpm / 60.0;
            deck.hasPosition = true;
        }
    }
    deck.effectiveBpm = loaded ? deck.bpm->get() : 0.0;
    const double fileBpm = loaded ? deck.track->getBpm() : 0.0;
    deck.rate = fileBpm > 0 && deck.effectiveBpm > 0 ? deck.effectiveBpm / fileBpm : 1.0;

    // Discrete changes are sent at once (§8.4)
    if (playing != deck.playing) {
        QJsonObject upd = positionFields(deck);
        upd[QStringLiteral("playing")] = playing;
        m_pEmitter->updateDeck(deck.number, upd);
        if (playing) {
            m_pEmitter->event(QStringLiteral("track.start"), -1, deck.number);
        } else {
            const double duration = deck.track ? deck.track->getDuration() : 0.0;
            const bool atEnd = duration > 0 && deck.positionS >= duration - 0.5;
            m_pEmitter->event(QStringLiteral("track.stop"),
                    -1,
                    deck.number,
                    QJsonObject{{QStringLiteral("kind"),
                            atEnd ? QStringLiteral("end") : QStringLiteral("pause")}});
        }
        deck.playing = playing;
        if (deck.number == m_sourceDeck) {
            m_needsReanchor = true;
        }
    }
    if (scratching != deck.scratching || slip != deck.slipActive) {
        if (scratching != deck.scratching) {
            m_pEmitter->event(scratching ? QStringLiteral("scratch.start") : QStringLiteral("scratch.end"),
                    -1,
                    deck.number);
            if (!scratching) {
                deck.scratchEndBeat = deck.beat;
            }
        }
        QJsonObject slipObj;
        slipObj[QStringLiteral("active")] = slip;
        slipObj[QStringLiteral("position_s")] = slip ? QJsonValue(round3(deck.slipPositionS)) : QJsonValue();
        QJsonObject upd = positionFields(deck);
        upd[QStringLiteral("scratching")] = scratching;
        upd[QStringLiteral("slip")] = slipObj;
        m_pEmitter->updateDeck(deck.number, upd);
        deck.scratching = scratching;
        deck.slipActive = slip;
    }
    if (loopOn != deck.loopActive) {
        const double inS = deck.loopStart->get() / mixxx::kEngineChannelOutputCount / deck.sampleRate;
        const double outS = deck.loopEnd->get() / mixxx::kEngineChannelOutputCount / deck.sampleRate;
        QJsonObject loop;
        loop[QStringLiteral("active")] = loopOn;
        loop[QStringLiteral("in_s")] = loopOn && inS >= 0 ? QJsonValue(round3(inS)) : QJsonValue();
        loop[QStringLiteral("out_s")] = loopOn && outS > inS ? QJsonValue(round3(outS)) : QJsonValue();
        m_pEmitter->updateDeck(deck.number, QJsonObject{{QStringLiteral("loop"), loop}});
        double beats = 0;
        if (deck.beats && outS > inS) {
            beats = round3(mixxx::vertexav::beatIndexAt(deck.beats,
                                   mixxx::audio::FramePos(outS * deck.sampleRate)) -
                    mixxx::vertexav::beatIndexAt(deck.beats, mixxx::audio::FramePos(inS * deck.sampleRate)));
        }
        m_pEmitter->event(loopOn ? QStringLiteral("loop.on") : QStringLiteral("loop.off"),
                -1,
                deck.number,
                QJsonObject{{QStringLiteral("in_s"), round3(inS)},
                        {QStringLiteral("out_s"), round3(outS)},
                        {QStringLiteral("beats"), beats}});
        deck.loopActive = loopOn;
    }
    if (pflOn != deck.pflOn) {
        m_pEmitter->updateDeck(deck.number, QJsonObject{{QStringLiteral("pfl"), pflOn}});
        deck.pflOn = pflOn;
    }

    // Jumps: hotcues, seeks, beat jumps and loop wraps.
    if (deck.hasPosition && playing && !scratching && deck.lastT >= 0 && deck.effectiveBpm > 0) {
        const double expected = deck.lastBeat + (now - deck.lastT) / 1e6 * deck.effectiveBpm / 60.0;
        if (std::abs(deck.beat - expected) > kJumpThresholdBeats) {
            const bool loopWrap = loopOn && deck.beat < deck.lastBeat;
            if (!loopWrap) {
                const double fromS = deck.positionS -
                        (deck.beat - deck.lastBeat) * 60.0 / std::max(1.0, deck.effectiveBpm) * deck.rate;
                m_pEmitter->event(QStringLiteral("seek"),
                        -1,
                        deck.number,
                        QJsonObject{{QStringLiteral("from_s"), round3(std::max(0.0, fromS))},
                                {QStringLiteral("to_s"), round3(deck.positionS)}});
            }
            m_pEmitter->updateDeck(deck.number, positionFields(deck));
            if (deck.number == m_sourceDeck) {
                m_needsReanchor = true;
            }
        }
    }
    if (std::abs(deck.rate - deck.sentRate) > 0.0005 || std::abs(deck.effectiveBpm - deck.sentBpm) > 0.01) {
        deck.sentRate = deck.rate;
        deck.sentBpm = deck.effectiveBpm;
        m_pEmitter->updateDeck(deck.number, positionFields(deck));
    }
    deck.lastBeat = deck.beat;
    deck.lastT = deck.hasPosition ? now : -1;

    // Continuous values: the emitter applies batching and the dead zone; only send changes.
    QJsonObject eq;
    eq[QStringLiteral("low")] = round3(eqNormalized(deck.eqLow.get(1.0)));
    eq[QStringLiteral("mid")] = round3(eqNormalized(deck.eqMid.get(1.0)));
    eq[QStringLiteral("high")] = round3(eqNormalized(deck.eqHigh.get(1.0)));
    eq[QStringLiteral("low_kill")] = deck.killLow.get(0) > 0;
    eq[QStringLiteral("mid_kill")] = deck.killMid.get(0) > 0;
    eq[QStringLiteral("high_kill")] = deck.killHigh.get(0) > 0;
    QJsonObject cont;
    cont[QStringLiteral("audible")] = deck.audible;
    cont[QStringLiteral("fader")] = round3(fader);
    cont[QStringLiteral("eq")] = eq;
    cont[QStringLiteral("filter")] = round3(std::clamp((deck.filter.get(0.5) - 0.5) * 2.0, -1.0, 1.0));
    if (cont != deck.sentContinuous) {
        deck.sentContinuous = cont;
        m_pEmitter->updateDeck(deck.number, cont);
    }
}

// ------------------------------------------------------------------ tempo (§9)

void VertexAVManager::publishTempo(qint64 now, double masterBeat, bool phaseReset) {
    m_pTempo->anchorT = now + m_extraLatencyUs;
    m_pTempo->anchorBeat = masterBeat;
    m_pTempo->phaseReset = phaseReset;
    m_pEmitter->setTempo(*m_pTempo);
    m_pTempo->phaseReset = false;
    m_lastTempoPublish = now;
}

void VertexAVManager::updateTempo(qint64 now) {
    DeckState* pSrc = m_sourceDeck > 0 && m_sourceDeck <= static_cast<int>(m_decks.size())
            ? m_decks[m_sourceDeck - 1].get()
            : nullptr;
    const qint64 t = now + m_extraLatencyUs;
    if (!pSrc || !pSrc->track || !pSrc->beats || !pSrc->hasPosition || pSrc->effectiveBpm <= 0) {
        if (m_pTempo->playing) {
            m_pTempo->playing = false;
            publishTempo(now, m_pTempo->beatAt(t), false);
        }
        m_needsReanchor = true;
        return;
    }
    vertexav::Stability stability = vertexav::Stability::Stable;
    if (pSrc->scratching) {
        // Scratch: freeze the phase, unless Slip Mode keeps a virtual timeline (§9.4).
        stability = pSrc->slipActive ? vertexav::Stability::Freewheel : vertexav::Stability::Unstable;
    } else if (!std::isnan(pSrc->scratchEndBeat)) {
        if (pSrc->beat - pSrc->scratchEndBeat < 1.0 && pSrc->beat >= pSrc->scratchEndBeat) {
            stability = vertexav::Stability::Unstable; // wait one beat after the scratch
        } else {
            pSrc->scratchEndBeat = std::nan("");
            m_needsReanchor = true;
        }
    }
    const double b = pSrc->scratching && pSrc->slipActive ? pSrc->slipBeat : pSrc->beat;
    m_pTempo->sourceDeck = pSrc->number;
    m_pTempo->beatsPerBar = 4;
    m_pTempo->confidence = 1.0;

    if (!pSrc->playing) {
        if (m_pTempo->playing) {
            m_pTempo->playing = false;
            publishTempo(now, b + m_masterOffset, false);
        }
        m_needsReanchor = true;
        return;
    }
    if (stability == vertexav::Stability::Unstable) {
        if (m_pTempo->stability != vertexav::Stability::Unstable) {
            m_pTempo->stability = vertexav::Stability::Unstable;
            m_pEmitter->setTempo(*m_pTempo); // same anchor, flagged unstable
        }
        return;
    }
    const double master = m_pTempo->playing ? m_pTempo->beatAt(t) : m_pTempo->anchorBeat;
    if (m_needsReanchor) {
        // Integer offset: master beats fall on deck beats. A fractional difference is a phase
        // jump (seek, scratch without slip, deck change with another phase).
        m_masterOffset = std::round(master - b);
        const double newMaster = b + m_masterOffset;
        const bool phaseReset = !m_pTempo->playing || std::abs(newMaster - master) > 0.02;
        m_pTempo->bpm = pSrc->effectiveBpm;
        m_pTempo->playing = true;
        m_pTempo->stability = stability;
        m_pTempo->barOffset = std::fmod(std::fmod(m_masterOffset, 4.0) + 4.0, 4.0);
        publishTempo(now, newMaster, phaseReset);
        m_needsReanchor = false;
        return;
    }
    const double drift = (b + m_masterOffset) - master;
    const double driftUs = std::abs(drift) * 60e6 / pSrc->effectiveBpm;
    const bool bpmChanged = std::abs(pSrc->effectiveBpm - m_pTempo->bpm) > 0.005;
    const bool stabilityChanged = stability != m_pTempo->stability;
    const qint64 since = now - m_lastTempoPublish;
    if (stabilityChanged || (bpmChanged && since >= kMinTempoIntervalUs) ||
            (driftUs > kMaxDriftUs && since >= kMinDriftIntervalUs)) {
        m_pTempo->bpm = pSrc->effectiveBpm;
        m_pTempo->stability = stability;
        publishTempo(now, b + m_masterOffset, std::abs(drift) > 0.25);
    }
}

// ------------------------------------------------------------------ structure (§11)

void VertexAVManager::scheduleSectionEvents(qint64 now) {
    QSet<QString> live;
    DeckState* pSrc = m_sourceDeck > 0 && m_sourceDeck <= static_cast<int>(m_decks.size())
            ? m_decks[m_sourceDeck - 1].get()
            : nullptr;
    const qint64 lookahead = m_pEmitter->config().lookaheadUs;
    if (pSrc && pSrc->playing && pSrc->hasPosition && m_pTempo->playing &&
            m_pTempo->stability != vertexav::Stability::Unstable && pSrc->info.hasSections) {
        double loopEndBeat = 1e12;
        if (pSrc->loopActive && pSrc->beats) {
            loopEndBeat = mixxx::vertexav::beatIndexAt(pSrc->beats,
                    mixxx::audio::FramePos(pSrc->loopEnd->get() / mixxx::kEngineChannelOutputCount));
        }
        const auto& sections = pSrc->info.sections;
        for (int idx = 1; idx < sections.size(); ++idx) {
            const auto& sec = sections[idx];
            const auto& prev = sections[idx - 1];
            QList<int> counts{0};
            if (sec.role == QLatin1String("drop") || sec.energy - prev.energy > 0.3) {
                counts << 16 << 8 << 4 << 2 << 1;
            }
            for (int n : std::as_const(counts)) {
                const double beat = sec.startBeat - n;
                if (beat <= pSrc->beat || beat >= loopEndBeat) {
                    continue;
                }
                const qint64 at = m_pTempo->timeOfBeat(beat + m_masterOffset);
                if (at - (now + m_extraLatencyUs) > lookahead) {
                    continue;
                }
                const QString key = QStringLiteral("%1/%2/%3/%4/%5")
                                            .arg(pSrc->info.trackId)
                                            .arg(pSrc->number)
                                            .arg(idx)
                                            .arg(n)
                                            .arg(m_masterOffset);
                live.insert(key);
                if (m_announced.contains(key) || m_doneEvents.contains(key)) {
                    continue;
                }
                QString id;
                if (n == 0) {
                    id = m_pEmitter->event(QStringLiteral("section.change"),
                            at,
                            pSrc->number,
                            QJsonObject{{QStringLiteral("from"), prev.role},
                                    {QStringLiteral("to"), sec.role},
                                    {QStringLiteral("section_index"), idx},
                                    {QStringLiteral("energy"), sec.energy}});
                } else {
                    const qint64 targetAt = m_pTempo->timeOfBeat(sec.startBeat + m_masterOffset);
                    id = m_pEmitter->event(QStringLiteral("countdown"),
                            at,
                            pSrc->number,
                            QJsonObject{{QStringLiteral("target"), sec.role},
                                    {QStringLiteral("beats_remaining"), n},
                                    {QStringLiteral("target_at"), QJsonValue(static_cast<qint64>(targetAt))}});
                }
                m_announced.insert(key, qMakePair(id, at));
            }
        }
    }
    const qint64 t = now + m_extraLatencyUs;
    for (auto it = m_announced.begin(); it != m_announced.end();) {
        if (it.value().second <= t) {
            m_doneEvents.insert(it.key());
            it = m_announced.erase(it);
        } else if (!live.contains(it.key())) {
            m_pEmitter->cancelEvent(it.value().first,
                    pSrc && pSrc->loopActive ? QStringLiteral("loop") : QStringLiteral("seek"));
            it = m_announced.erase(it);
        } else {
            ++it;
        }
    }
    if (m_doneEvents.size() > 2000) {
        m_doneEvents.clear();
    }
}

void VertexAVManager::trackSections(qint64 now) {
    Q_UNUSED(now);
    DeckState* pSrc = m_sourceDeck > 0 && m_sourceDeck <= static_cast<int>(m_decks.size())
            ? m_decks[m_sourceDeck - 1].get()
            : nullptr;
    if (!pSrc || !pSrc->hasPosition || pSrc->info.sections.isEmpty()) {
        return;
    }
    int index = -1;
    for (int i = 0; i < pSrc->info.sections.size(); ++i) {
        const auto& s = pSrc->info.sections[i];
        if (s.startBeat <= pSrc->beat && pSrc->beat < s.endBeat) {
            index = i;
            break;
        }
    }
    if (index == m_currentSection && pSrc->number == m_currentSectionDeck) {
        return;
    }
    m_currentSection = index;
    m_currentSectionDeck = pSrc->number;
    if (index >= 0) {
        applyIntent(*pSrc, index);
    }
}

void VertexAVManager::applyIntent(DeckState& deck, int sectionIndex) {
    const auto& sec = deck.info.sections[sectionIndex];
    QJsonArray palette;
    for (const QString& c : std::as_const(deck.info.palette)) {
        palette.append(c);
    }
    QJsonObject intent;
    intent[QStringLiteral("energy")] = sec.energy;
    intent[QStringLiteral("mood")] = deck.info.mood;
    intent[QStringLiteral("palette")] = palette;
    intent[QStringLiteral("intensity_hint")] = intensityFor(sec.energy);
    intent[QStringLiteral("strobe_ok")] =
            (sec.role == QLatin1String("drop") || sec.role == QLatin1String("chorus")) && sec.energy >= 0.5;
    m_pEmitter->updateIntent(intent);
}
